import UIKit
import ImageIO
import CryptoKit

/**
 * [EN] Options for `UIImage.cyl_load(with:options:completion:)`. Swift only: Objective-C keeps the `NS_OPTIONS` of the
 *      same name in `UIImage+CYLTabBarControllerExtention.h` (same values), and its calls pass the raw value.
 * [CN] `UIImage.cyl_load(with:options:completion:)` 的选项。仅 Swift 使用：Objective-C 保留
 *      `UIImage+CYLTabBarControllerExtention.h` 中同名的 `NS_OPTIONS`（取值相同），调用时传入原始值。
 */
public struct CYLImageLoadOptions: OptionSet {
    public let rawValue: UInt

    public init(rawValue: UInt) {
        self.rawValue = rawValue
    }

    /**
     * [EN] Download again even when the image is cached.
     * [CN] 即使已缓存也重新下载。
     */
    public static let refreshCached = CYLImageLoadOptions(rawValue: 1 << 0)
    /**
     * [EN] Use the cache only, never the network.
     * [CN] 只使用缓存，不访问网络。
     */
    public static let fromCacheOnly = CYLImageLoadOptions(rawValue: 1 << 1)
    /**
     * [EN] Keep a downloaded image in memory only, not on disk.
     * [CN] 下载的图片只保存在内存中，不写入磁盘。
     */
    public static let memoryCacheOnly = CYLImageLoadOptions(rawValue: 1 << 2)
    /**
     * [EN] Do not keep the image in the memory cache.
     * [CN] 不把图片放入内存缓存。
     */
    public static let avoidMemoryCache = CYLImageLoadOptions(rawValue: 1 << 3)
}

/**
 * [EN] Which date of a cached file decides its age.
 * [CN] 由缓存文件的哪个日期决定其存放时间。
 */
@objc public enum CYLImageCacheExpireType: Int {
    /**
     * [EN] The last access.
     * [CN] 最后访问时间。
     */
    case accessDate
    /**
     * [EN] The last modification.
     * [CN] 最后修改时间。
     */
    case modificationDate
}

/**
 * [EN] The memory and disk cache of images loaded by URL (tab icons from the network). Translated from Objective-C
 *      (docs/Swift-Migration.md); Objective-C callers get this class from `CYLSwiftInterface.h`; Swift names kept
 *      (`CYLImageCache.shared()`).
 * [CN] 通过 URL 加载的图片（网络 Tab 图标）的内存与磁盘缓存。已从 Objective-C 翻译（docs/Swift-Migration.md）；Objective-C 调用方通过
 *      `CYLSwiftInterface.h` 使用本类；Swift 名称不变（`CYLImageCache.shared()`）。
 */
@objc(CYLImageCache)
public class CYLImageCache: NSObject {

    private static let sharedCache = CYLImageCache()

    /**
     * [EN] The cache shared by every tab bar.
     * [CN] 所有 TabBar 共用的缓存。
     */
    @objc(sharedImageCache)
    public class func shared() -> CYLImageCache {
        sharedCache
    }

    private let memoryCache = NSCache<NSString, UIImage>()
    private let ioQueue = DispatchQueue(label: "com.chenyilong.CYLTabBarController.CYLImageCache")

    /**
     * [EN] Whether images are kept in memory (default true).
     * [CN] 是否在内存中缓存图片（默认 true）。
     */
    @objc public var shouldCacheImagesInMemory = true
    /**
     * [EN] Whether downloaded data is kept on disk (default true).
     * [CN] 是否在磁盘上缓存下载的数据（默认 true）。
     */
    @objc public var shouldCacheImagesOnDisk = true
    /**
     * [EN] The largest number of images in memory (default 100).
     * [CN] 内存中图片的最大数量（默认 100）。
     */
    @objc public var maxMemoryCount: UInt = 100 {
        didSet { memoryCache.countLimit = Int(maxMemoryCount) }
    }
    /**
     * [EN] The largest memory cost in bytes (0: no limit).
     * [CN] 内存占用的最大字节数（0：不限制）。
     */
    @objc public var maxMemoryCost: UInt = 0 {
        didSet { memoryCache.totalCostLimit = Int(maxMemoryCost) }
    }
    /**
     * [EN] The longest time a file stays on disk (default one week; 0 or less: forever).
     * [CN] 文件在磁盘上保存的最长时间（默认一周；0 或负数：永久）。
     */
    @objc public var maxDiskAge: TimeInterval = 7 * 24 * 60 * 60
    /**
     * [EN] Which date decides a file's age (default the last access).
     * [CN] 由哪个日期决定文件的存放时间（默认最后访问时间）。
     */
    @objc public var diskCacheExpireType: CYLImageCacheExpireType = .accessDate
    /**
     * [EN] The largest disk size in bytes (0: no limit); above it, the oldest files go until half of it is left.
     * [CN] 磁盘占用的最大字节数（0：不限制）；超过时删除最旧的文件，直到剩下一半。
     */
    @objc public var maxDiskSize: UInt = 0
    /**
     * [EN] The folder of the disk cache.
     * [CN] 磁盘缓存的目录。
     */
    @objc public var diskCachePath: String
    /**
     * [EN] The download timeout in seconds (default 15).
     * [CN] 下载超时时间，单位秒（默认 15）。
     */
    @objc public var downloadTimeout: TimeInterval = 15

    override public init() {
        let caches = NSSearchPathForDirectoriesInDomains(.cachesDirectory, .userDomainMask, true).first ?? NSTemporaryDirectory()
        diskCachePath = (caches as NSString).appendingPathComponent("CYLTabBarController/RemoteImages")
        super.init()
        memoryCache.countLimit = Int(maxMemoryCount)
        let center = NotificationCenter.default
        center.addObserver(self, selector: #selector(clearMemory), name: UIApplication.didReceiveMemoryWarningNotification,
                           object: nil)
        center.addObserver(self, selector: #selector(applicationDidEnterBackground),
                           name: UIApplication.didEnterBackgroundNotification, object: nil)
        center.addObserver(self, selector: #selector(applicationWillTerminate), name: UIApplication.willTerminateNotification,
                           object: nil)
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    // MARK: - Public

    /**
     * [EN] The cached image of `URL` (memory, then disk), or nil.
     * [CN] `URL` 对应的缓存图片（先内存后磁盘），没有时为 nil。
     */
    @objc(imageFromCacheForURL:)
    public func imageFromCache(for URL: URL?) -> UIImage? {
        guard let URL else {
            return nil
        }
        let key = CYLImageCache.key(for: URL)
        if let image = memoryCache.object(forKey: key as NSString) {
            return image
        }
        let data = ioQueue.sync { diskData(forKey: key) }
        guard let image = data.flatMap(CYLImageCache.image(with:)) else {
            return nil
        }
        storeInMemory(image, forKey: key)
        return image
    }

    /**
     * [EN] Removes the image of `URL` from memory and disk.
     * [CN] 从内存与磁盘中移除 `URL` 对应的图片。
     */
    @objc(removeImageForURL:)
    public func removeImage(for URL: URL?) {
        guard let URL else {
            return
        }
        let key = CYLImageCache.key(for: URL)
        memoryCache.removeObject(forKey: key as NSString)
        ioQueue.async {
            try? FileManager.default.removeItem(atPath: self.filePath(forKey: key))
        }
    }

    /**
     * [EN] Empties the memory cache (also on a memory warning).
     * [CN] 清空内存缓存（收到内存警告时也会清空）。
     */
    @objc public func clearMemory() {
        memoryCache.removeAllObjects()
    }

    /**
     * [EN] Empties the disk cache; `completion` runs on the main queue.
     * [CN] 清空磁盘缓存；`completion` 在主队列执行。
     */
    @objc(clearDiskOnCompletion:)
    public func clearDisk(onCompletion completion: (() -> Void)?) {
        ioQueue.async {
            try? FileManager.default.removeItem(atPath: self.diskCachePath)
            if let completion {
                DispatchQueue.main.async(execute: completion)
            }
        }
    }

    /**
     * [EN] Deletes expired files, then the oldest ones above `maxDiskSize`; `completion` runs on the main queue.
     * [CN] 删除过期文件，再删除超出 `maxDiskSize` 的最旧文件；`completion` 在主队列执行。
     */
    @objc(deleteOldFilesWithCompletion:)
    public func deleteOldFiles(completion: (() -> Void)?) {
        ioQueue.async {
            self.deleteOldFilesNow()
            if let completion {
                DispatchQueue.main.async(execute: completion)
            }
        }
    }

    /**
     * [EN] The size of the disk cache in bytes.
     * [CN] 磁盘缓存的字节数。
     */
    @objc public func totalDiskSize() -> UInt {
        ioQueue.sync {
            var size: UInt = 0
            let fileManager = FileManager.default
            for case let fileName as String in fileManager.enumerator(atPath: diskCachePath) ?? NSEnumerator() {
                let attributes = try? fileManager.attributesOfItem(atPath: filePath(forKey: fileName))
                size += (attributes?[.size] as? NSNumber)?.uintValue ?? 0
            }
            return size
        }
    }

    // MARK: - Loading

    func loadImage(with URL: URL, options: CYLImageLoadOptions, finish: @escaping (UIImage?) -> Void) {
        let key = CYLImageCache.key(for: URL)
        let refreshes = options.contains(.refreshCached)
        let keepsInMemory = !options.contains(.avoidMemoryCache)
        if !refreshes, let image = memoryCache.object(forKey: key as NSString) {
            finish(image)
            return
        }
        ioQueue.async {
            if !refreshes, let data = self.diskData(forKey: key), let image = CYLImageCache.image(with: data) {
                if keepsInMemory {
                    self.storeInMemory(image, forKey: key)
                }
                finish(image)
                return
            }
            if options.contains(.fromCacheOnly) {
                finish(nil)
                return
            }
            let request = URLRequest(url: URL, cachePolicy: refreshes ? .reloadIgnoringLocalCacheData : .useProtocolCachePolicy,
                                     timeoutInterval: self.downloadTimeout)
            URLSession.shared.dataTask(with: request) { data, response, error in
                let statusCode = (response as? HTTPURLResponse)?.statusCode ?? 200
                let image = (error == nil && statusCode / 100 == 2) ? data.flatMap(CYLImageCache.image(with:)) : nil
                if let image, let data {
                    if keepsInMemory {
                        self.storeInMemory(image, forKey: key)
                    }
                    if !options.contains(.memoryCacheOnly) {
                        self.store(data, forKey: key)
                    }
                }
                finish(image)
            }.resume()
        }
    }

    // MARK: - Private

    private static func key(for URL: URL) -> String {
        SHA256.hash(data: Data(URL.absoluteString.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    private static func image(with data: Data) -> UIImage? {
        if data.count > 4, data.prefix(4) == Data("GIF8".utf8) {
            return UIImage.cyl_animatedImage(withGIFData: data)
        }
        return UIImage(data: data, scale: UIScreen.main.scale)
    }

    private func filePath(forKey key: String) -> String {
        (diskCachePath as NSString).appendingPathComponent(key)
    }

    private func storeInMemory(_ image: UIImage, forKey key: String) {
        guard shouldCacheImagesInMemory else {
            return
        }
        let frames = max(image.images?.count ?? 0, 1)
        let cost = Int(image.size.width * image.scale * image.size.height * image.scale * 4) * frames
        memoryCache.setObject(image, forKey: key as NSString, cost: cost)
    }

    private var dateKey: URLResourceKey {
        diskCacheExpireType == .accessDate ? .contentAccessDateKey : .contentModificationDateKey
    }

    private func isExpiredFile(at fileURL: URL) -> Bool {
        guard maxDiskAge > 0 else {
            return false
        }
        let date = (try? (fileURL as NSURL).resourceValues(forKeys: [dateKey]))?[dateKey] as? Date
        return date.map { -$0.timeIntervalSinceNow > maxDiskAge } ?? true
    }

    private func diskData(forKey key: String) -> Data? {
        let fileURL = URL(fileURLWithPath: filePath(forKey: key))
        guard FileManager.default.fileExists(atPath: fileURL.path), !isExpiredFile(at: fileURL),
              let data = try? Data(contentsOf: fileURL) else {
            return nil
        }
        try? (fileURL as NSURL).setResourceValue(Date(), forKey: .contentAccessDateKey)
        return data
    }

    private func store(_ data: Data, forKey key: String) {
        guard shouldCacheImagesOnDisk, !data.isEmpty else {
            return
        }
        ioQueue.async {
            try? FileManager.default.createDirectory(atPath: self.diskCachePath, withIntermediateDirectories: true)
            try? data.write(to: URL(fileURLWithPath: self.filePath(forKey: key)), options: .atomic)
        }
    }

    private func deleteOldFilesNow() {
        let fileManager = FileManager.default
        let keys: [URLResourceKey] = [.isDirectoryKey, .contentAccessDateKey, .contentModificationDateKey,
                                      .totalFileAllocatedSizeKey]
        let directoryURL = URL(fileURLWithPath: diskCachePath, isDirectory: true)
        let fileURLs = (try? fileManager.contentsOfDirectory(at: directoryURL, includingPropertiesForKeys: keys,
                                                             options: .skipsHiddenFiles)) ?? []
        var remaining: [(url: URL, size: UInt, date: Date)] = []
        var totalSize: UInt = 0
        for fileURL in fileURLs {
            let values = (try? (fileURL as NSURL).resourceValues(forKeys: keys)) ?? [:]
            if (values[.isDirectoryKey] as? NSNumber)?.boolValue == true {
                continue
            }
            if isExpiredFile(at: fileURL) {
                try? fileManager.removeItem(at: fileURL)
                continue
            }
            let size = (values[.totalFileAllocatedSizeKey] as? NSNumber)?.uintValue ?? 0
            totalSize += size
            remaining.append((fileURL, size, values[dateKey] as? Date ?? .distantPast))
        }
        guard maxDiskSize > 0, totalSize > maxDiskSize else {
            return
        }
        let targetSize = maxDiskSize / 2
        for file in remaining.sorted(by: { $0.date < $1.date }) {
            if totalSize <= targetSize {
                break
            }
            if (try? fileManager.removeItem(at: file.url)) != nil {
                totalSize -= min(totalSize, file.size)
            }
        }
    }

    @objc private func applicationDidEnterBackground() {
        let application = UIApplication.shared
        var taskIdentifier = UIBackgroundTaskIdentifier.invalid
        taskIdentifier = application.beginBackgroundTask {
            application.endBackgroundTask(taskIdentifier)
            taskIdentifier = .invalid
        }
        deleteOldFiles {
            application.endBackgroundTask(taskIdentifier)
            taskIdentifier = .invalid
        }
    }

    @objc private func applicationWillTerminate() {
        deleteOldFiles(completion: nil)
    }
}

/**
 * [EN] Images from colors, light / dark pairs, names or image info, GIF data and URLs. Translated from Objective-C
 *      (docs/Swift-Migration.md); Objective-C callers get the declarations from `CYLSwiftInterface.h`; the Swift names are
 *      the ones Clang imported.
 * [CN] 由颜色、浅色/深色图片对、名称或图片信息、GIF 数据和 URL 生成图片。已从 Objective-C 翻译（docs/Swift-Migration.md）；
 *      Objective-C 调用方从 `CYLSwiftInterface.h` 获得声明；Swift 名称与 Clang 原先导入的名称相同。
 */
extension UIImage {

    private static var darkImageNameSuffixStorage: String? = "_dark"

    // MARK: - Loading by URL

    /**
     * [EN] Loads the image at `URL` through `CYLImageCache`; `completion` runs on the main queue.
     * [CN] 通过 `CYLImageCache` 加载 `URL` 处的图片；`completion` 在主队列执行。
     */
    @objc(cyl_loadImageWithURL:completion:)
    public class func cyl_load(with URL: URL?, completion: @escaping (UIImage?) -> Void) {
        cyl_load(with: URL, options: [], completion: completion)
    }

    /**
     * [EN] Loads the image at `URL` with options; `completion` runs on the main queue.
     * [CN] 按选项加载 `URL` 处的图片；`completion` 在主队列执行。
     */
    public class func cyl_load(with URL: URL?, options: CYLImageLoadOptions, completion: @escaping (UIImage?) -> Void) {
        let finish: (UIImage?) -> Void = { image in
            DispatchQueue.main.async {
                completion(image)
            }
        }
        guard let URL else {
            finish(nil)
            return
        }
        CYLImageCache.shared().loadImage(with: URL, options: options, finish: finish)
    }

    /**
     * [EN] The Objective-C entry of `cyl_load(with:options:completion:)`: `options` is the raw value of
     *      `CYLImageLoadOptions`.
     * [CN] `cyl_load(with:options:completion:)` 的 Objective-C 入口：`options` 为 `CYLImageLoadOptions` 的原始值。
     */
    @objc(cyl_loadImageWithURL:options:completion:)
    public class func cyl_load(with URL: URL?, rawOptions: UInt, completion: @escaping (UIImage?) -> Void) {
        cyl_load(with: URL, options: CYLImageLoadOptions(rawValue: rawOptions), completion: completion)
    }

    // MARK: - GIF

    /**
     * [EN] The delay of one GIF frame (0.1 s for a delay under 11 ms, as browsers do).
     * [CN] 一帧 GIF 的延迟（小于 11 毫秒时为 0.1 秒，与浏览器一致）。
     */
    @objc(cyl_GIFFrameDelayWithProperties:)
    public class func cyl_GIFFrameDelay(withProperties properties: [AnyHashable: Any]) -> TimeInterval {
        let gif = properties[kCGImagePropertyGIFDictionary as String] as? [AnyHashable: Any]
        var delay = (gif?[kCGImagePropertyGIFUnclampedDelayTime as String] as? NSNumber)?.doubleValue ?? 0
        if delay <= 0 {
            delay = (gif?[kCGImagePropertyGIFDelayTime as String] as? NSNumber)?.doubleValue ?? 0
        }
        return delay < 0.011 ? 0.1 : delay
    }

    /**
     * [EN] An animated image from GIF data (a still image for one frame, nil for no frame).
     * [CN] 由 GIF 数据生成的动图（只有一帧时为静态图片，没有帧时为 nil）。
     */
    @objc(cyl_animatedImageWithGIFData:)
    public class func cyl_animatedImage(withGIFData data: Data) -> UIImage? {
        guard !data.isEmpty, let source = CGImageSourceCreateWithData(data as CFData, nil) else {
            return nil
        }
        let scale = UIScreen.main.scale
        var frames: [UIImage] = []
        var duration: TimeInterval = 0
        for index in 0..<CGImageSourceGetCount(source) {
            guard let imageRef = CGImageSourceCreateImageAtIndex(source, index, nil) else {
                continue
            }
            frames.append(UIImage(cgImage: imageRef, scale: scale, orientation: .up))
            let properties = CGImageSourceCopyPropertiesAtIndex(source, index, nil) as? [AnyHashable: Any] ?? [:]
            duration += cyl_GIFFrameDelay(withProperties: properties)
        }
        if frames.count <= 1 {
            return frames.first
        }
        return UIImage.animatedImage(with: frames, duration: duration)
    }

    // MARK: - Colors

    /**
     * [EN] An image of one color (rendered as original), nil without a color or a size.
     * [CN] 单色图片（以原图渲染），没有颜色或尺寸时为 nil。
     */
    @objc(cyl_imageWithColor:size:)
    public class func cyl_image(with color: UIColor?, size: CGSize) -> UIImage? {
        guard let color, size.width > 0, size.height > 0 else {
            return nil
        }
        return image(with: color, size: size, cornerRadius: 0, renderingMode: .alwaysOriginal)
    }

    /**
     * [EN] An image of one color with rounded corners; a dynamic color gives a light / dark pair.
     * [CN] 带圆角的单色图片；动态颜色会生成浅色/深色图片对。
     */
    @objc(cyl_imageWithColor:size:cornerRadius:)
    public class func cyl_image(with color: UIColor?, size: CGSize, cornerRadius: CGFloat) -> UIImage? {
        image(with: color ?? .clear, size: size, cornerRadius: cornerRadius, renderingMode: .automatic)
    }

    // MARK: - Dark mode (#552, #620)

    /**
     * [EN] One image that is `lightImage` in light mode and `darkImage` in dark mode; either one alone when the other is nil.
     * [CN] 浅色模式为 `lightImage`、深色模式为 `darkImage` 的图片；其中一个为 nil 时直接返回另一个。
     */
    @objc(cyl_imageWithLightImage:darkImage:)
    public class func cyl_image(withLight lightImage: UIImage?, dark darkImage: UIImage?) -> UIImage? {
        guard let lightImage, let darkImage else {
            return lightImage ?? darkImage
        }
        let light = variant(of: lightImage, for: .light)
        let dark = variant(of: darkImage, for: .dark)
        let anyTraits = UITraitCollection(displayScale: light.scale)
        let darkTraits = UITraitCollection(traitsFrom: [UITraitCollection(displayScale: dark.scale),
                                                        UITraitCollection(userInterfaceStyle: .dark)])
        let imageAsset = UIImageAsset()
        imageAsset.register(forRegistering(light), with: anyTraits)
        imageAsset.register(forRegistering(dark), with: darkTraits)
        return imageAsset.image(with: UITraitCollection.current)
    }

    /**
     * [EN] The image of `imageInfo` (a name or an image) with the dark one of `darkImageInfo`.
     * [CN] `imageInfo`（名称或图片）对应的图片，以及 `darkImageInfo` 对应的深色图片。
     */
    @objc(cyl_imageWithImageInfo:darkImageInfo:)
    public class func cyl_image(withImageInfo imageInfo: Any?, darkImageInfo: Any?) -> UIImage? {
        let image = imageInfo.flatMap { cyl_getImage(fromImageInfo: $0) }
        guard let darkImage = darkImageInfo.flatMap({ cyl_getImage(fromImageInfo: $0) }) else {
            return image
        }
        return cyl_image(withLight: image, dark: darkImage)
    }

    /**
     * [EN] Same as `cyl_image(withLight:dark:)`.
     * [CN] 与 `cyl_image(withLight:dark:)` 相同。
     */
    @objc(cyl_lightOrDarkModeImageWithLightImage:darkImage:)
    public class func cyl_lightOrDarkModeImage(withLightImage lightImage: UIImage?, darkImage: UIImage?) -> UIImage? {
        cyl_image(withLight: lightImage, dark: darkImage)
    }

    /**
     * [EN] The light / dark image resolved for the traits of `owner`.
     * [CN] 按 `owner` 的特征解析出的浅色/深色图片。
     */
    @objc(cyl_lightOrDarkModeImageWithOwner:lightImage:darkImage:)
    public class func cyl_lightOrDarkModeImage(withOwner owner: UITraitEnvironment?, lightImage: UIImage?,
                                               darkImage: UIImage?) -> UIImage? {
        let image = cyl_image(withLight: lightImage, dark: darkImage)
        if let owner, let imageAsset = image?.imageAsset {
            return imageAsset.image(with: owner.traitCollection)
        }
        return image
    }

    /**
     * [EN] The light / dark image of two names resolved for `owner`; without a dark name, the light name's
     *      `cyl_darkImageNameSuffix` variant is used when it exists.
     * [CN] 按 `owner` 解析两个名称对应的浅色/深色图片；没有深色名称时，若存在带 `cyl_darkImageNameSuffix` 后缀的图片则使用它。
     */
    @objc(cyl_lightOrDarkModeImageWithOwner:lightImageName:darkImageName:)
    public class func cyl_lightOrDarkModeImage(withOwner owner: UITraitEnvironment?, lightImageName: String,
                                               darkImageName: String?) -> UIImage? {
        guard let darkImageName, !darkImageName.isEmpty else {
            let image = lightImageName.isEmpty ? nil : imageNamedFollowingDarkMode(lightImageName, renderingMode: .automatic)
            return cyl_lightOrDarkModeImage(withOwner: owner, lightImage: image, darkImage: nil)
        }
        let lightImage = lightImageName.isEmpty ? nil : UIImage(named: lightImageName)
        return cyl_lightOrDarkModeImage(withOwner: owner, lightImage: lightImage, darkImage: UIImage(named: darkImageName))
    }

    /**
     * [EN] The asset image `assetImageName` for a user interface style (`UIUserInterfaceStyle` raw value).
     * [CN] 资源图片 `assetImageName` 在某种界面风格（`UIUserInterfaceStyle` 原始值）下的图片。
     */
    @objc(cyl_assetImageName:userInterfaceStyle:)
    public class func cyl_assetImageName(_ assetImageName: String, userInterfaceStyle: Int) -> UIImage? {
        let image = UIImage(named: assetImageName)
        guard let style = UIUserInterfaceStyle(rawValue: userInterfaceStyle), style != .unspecified,
              let imageAsset = image?.imageAsset else {
            return image
        }
        return imageAsset.image(with: UITraitCollection(userInterfaceStyle: style))
    }

    /**
     * [EN] The suffix of the dark variant of an image name (default "_dark"; nil or empty turns it off).
     * [CN] 图片名称深色版本的后缀（默认 "_dark"；nil 或空字符串则关闭）。
     */
    @objc public class var cyl_darkImageNameSuffix: String? {
        @objc(cyl_darkImageNameSuffix) get { darkImageNameSuffixStorage }
        @objc(cyl_setDarkImageNameSuffix:) set { darkImageNameSuffixStorage = newValue?.isEmpty == false ? newValue : nil }
    }

    // MARK: - Image info

    /**
     * [EN] The image of `imageInfo`, or the tab item placeholder for nil.
     * [CN] `imageInfo` 对应的图片；为 nil 时返回 TabBarItem 占位图。
     */
    @objc(cyl_imageNamed:)
    public class func cyl_imageNamed(_ imageInfo: Any?) -> UIImage! {
        guard let imageInfo else {
            return cyl_tabItemPlaceholder()
        }
        return cyl_getImage(fromImageInfo: imageInfo)
    }

    /**
     * [EN] The image of `imageInfo`: a name (with its dark variant) or an image.
     * [CN] `imageInfo` 对应的图片：名称（含其深色版本）或图片。
     */
    @objc(cyl_getImageFromImageInfo:)
    public class func cyl_getImage(fromImageInfo imageInfo: Any) -> UIImage? {
        if let name = imageInfo as? String {
            return imageNamedFollowingDarkMode(name, renderingMode: .alwaysOriginal)
        }
        return imageInfo as? UIImage
    }

    /**
     * [EN] A clear 1 × 1 image for a tab without an icon.
     * [CN] 没有图标的 Tab 使用的 1 × 1 透明图片。
     */
    @objc(cyl_tabItemPlaceholderImage)
    public class func cyl_tabItemPlaceholder() -> UIImage {
        cyl_image(with: .clear, size: CGSize(width: 1, height: 1)) ?? UIImage()
    }

    // MARK: - Private

    private class func image(with color: UIColor, size: CGSize, cornerRadius: CGFloat,
                             renderingMode: UIImage.RenderingMode) -> UIImage? {
        let lightColor = color.resolvedColor(with: UITraitCollection(userInterfaceStyle: .light))
        let darkColor = color.resolvedColor(with: UITraitCollection(userInterfaceStyle: .dark))
        if lightColor != darkColor {
            let lightImage = staticImage(with: lightColor, size: size, cornerRadius: cornerRadius)
            let darkImage = staticImage(with: darkColor, size: size, cornerRadius: cornerRadius)
            return cyl_image(withLight: lightImage?.withRenderingMode(renderingMode),
                             dark: darkImage?.withRenderingMode(renderingMode))
        }
        return staticImage(with: color, size: size, cornerRadius: cornerRadius)?.withRenderingMode(renderingMode)
    }

    private class func staticImage(with color: UIColor, size: CGSize, cornerRadius: CGFloat) -> UIImage? {
        guard size.width > 0, size.height > 0 else {
            return nil
        }
        let format = UIGraphicsImageRendererFormat.preferred()
        format.opaque = cornerRadius == 0 && color.cgColor.alpha == 1
        return UIGraphicsImageRenderer(size: size, format: format).image { context in
            context.cgContext.setFillColor(color.cgColor)
            let rect = CGRect(origin: .zero, size: size)
            if cornerRadius > 0 {
                let path = UIBezierPath(roundedRect: rect, cornerRadius: cornerRadius)
                path.addClip()
                path.fill()
            } else {
                context.cgContext.fill(rect)
            }
        }
    }

    private class func forRegistering(_ image: UIImage) -> UIImage {
        guard let cgImage = image.cgImage else {
            return image
        }
        return UIImage(cgImage: cgImage, scale: image.scale, orientation: image.imageOrientation)
            .withRenderingMode(image.renderingMode)
    }

    private class func variant(of image: UIImage, for style: UIUserInterfaceStyle) -> UIImage {
        guard let imageAsset = image.imageAsset else {
            return image
        }
        let traits = UITraitCollection(traitsFrom: [UITraitCollection(displayScale: image.scale),
                                                    UITraitCollection(userInterfaceStyle: style)])
        return imageAsset.image(with: traits).withRenderingMode(image.renderingMode)
    }

    private class func darkImageName(for name: String) -> String? {
        let baseName = (name as NSString).deletingPathExtension
        guard let suffix = darkImageNameSuffixStorage, !suffix.isEmpty, !baseName.isEmpty, !baseName.hasSuffix(suffix) else {
            return nil
        }
        let darkName = baseName + suffix
        let pathExtension = (name as NSString).pathExtension
        return pathExtension.isEmpty ? darkName : (darkName as NSString).appendingPathExtension(pathExtension)
    }

    private class func hasDarkAppearance(_ image: UIImage) -> Bool {
        guard let imageAsset = image.imageAsset else {
            return false
        }
        let light = imageAsset.image(with: UITraitCollection(userInterfaceStyle: .light))
        let dark = imageAsset.image(with: UITraitCollection(userInterfaceStyle: .dark))
        return light !== dark && light.cgImage !== dark.cgImage
    }

    private class func imageNamedOrAtPath(_ name: String) -> UIImage? {
        (name as NSString).isAbsolutePath ? UIImage(contentsOfFile: name) : UIImage(named: name)
    }

    private class func imageNamedFollowingDarkMode(_ name: String, renderingMode: UIImage.RenderingMode) -> UIImage? {
        guard let image = imageNamedOrAtPath(name) else {
            return nil
        }
        if hasDarkAppearance(image) {
            return image.withRenderingMode(renderingMode)
        }
        let darkImage = darkImageName(for: name).flatMap(imageNamedOrAtPath)
        let lightImage = image.withRenderingMode(renderingMode)
        guard let darkImage else {
            return lightImage
        }
        return cyl_image(withLight: lightImage, dark: darkImage.withRenderingMode(renderingMode))
    }
}
